// Récupère le texte brut de l'IA
const rawContent = items[0].json.content.parts[0].text;
// Nettoie les balises Markdown ```json et ```
let cleanJson = rawContent.replace(/```json\n?|\n?```/g, "").trim();
try {
  // Parse le JSON pour s'assurer qu'il est valide
  const parsedData = JSON.parse(cleanJson);

  return [{
    json: parsedData
  }];
} catch (error) {
  // Fallback en cas d'erreur de parsing
  return [{
    json: {
      grade: 0,
      appreciation: "Erreur technique lors de l'analyse : " + error.message,
      subject: "Erreur"
    }
  }];
}
